package com.klef.soa.docker.dto;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * Request DTO for creating a Hostel
 * Note: No ID field is present here, as ID is strictly generated by the database.
 */
@Schema(description = "Payload required to register a new hostel")
public class HostelRequest {

    @NotBlank(message = "Hostel name cannot be empty")
    @Schema(description = "Name of the hostel", example = "Gargi Bhavan", requiredMode = Schema.RequiredMode.REQUIRED)
    private String hostelName;

    @NotBlank(message = "Location cannot be empty")
    @Schema(description = "Physical campus location or block", example = "North Campus, Sector 4", requiredMode = Schema.RequiredMode.REQUIRED)
    private String location;

    @NotNull(message = "Room count is required")
    @Min(value = 1, message = "Room count must be a positive integer greater than zero")
    @Schema(description = "Total number of student rooms (must be > 0)", example = "150", requiredMode = Schema.RequiredMode.REQUIRED)
    private Integer roomCount;

    @NotBlank(message = "Warden name cannot be empty")
    @Schema(description = "Full name of the designated warden", example = "Dr. Sunita Rao", requiredMode = Schema.RequiredMode.REQUIRED)
    private String wardenName;

    public HostelRequest() {
    }

    public HostelRequest(String hostelName, String location, Integer roomCount, String wardenName) {
        this.hostelName = hostelName;
        this.location = location;
        this.roomCount = roomCount;
        this.wardenName = wardenName;
    }

    public String getHostelName() {
        return hostelName;
    }

    public void setHostelName(String hostelName) {
        this.hostelName = hostelName;
    }

    public String getLocation() {
        return location;
    }

    public void setLocation(String location) {
        this.location = location;
    }

    public Integer getRoomCount() {
        return roomCount;
    }

    public void setRoomCount(Integer roomCount) {
        this.roomCount = roomCount;
    }

    public String getWardenName() {
        return wardenName;
    }

    public void setWardenName(String wardenName) {
        this.wardenName = wardenName;
    }
}
